"""The typed TypeScript client of the backend, generated by code from the OpenAPI contract (ADR-0016). React and
Angular import the same file: one interface `Api` with a method per operation and the request and response types;
`ApiError` (a business rejection, HTTP 422, with code, legacy code and message) comes from the fixed runtime file."""

from importlib import resources
from typing import Any

HEADER = "// Generated by the platform from the OpenAPI contract (ADR-0016). Do not edit: it follows the design (C3).\n"
RUNTIME = "client-runtime.ts"


def runtime() -> str:
    """The fixed part of the client (errors and the call over fetch), the same for every project."""
    return resources.files("nexti_pack_frontend").joinpath("client_runtime.ts").read_text(encoding="utf-8")


def _ts_type(schema: dict[str, Any]) -> str:
    if "enum" in schema:
        return " | ".join(f"'{v}'" for v in schema["enum"])
    kind = schema.get("type")
    if kind in ("number", "integer"):
        return "number"
    if kind == "boolean":
        return "boolean"
    return "string"


def _interface(name: str, schema: dict[str, Any]) -> str:
    lines = [f"export interface {name} {{"]
    for field, spec in schema.get("properties", {}).items():
        optional = "" if field in schema.get("required", []) else "?"
        lines.append(f"  /** {spec.get('x-neutral', spec.get('type', ''))} */")
        lines.append(f"  {field}{optional}: {_ts_type(spec)}")
    lines.append("}")
    return "\n".join(lines)


def _response_of(operation: dict[str, Any]) -> str:
    ref: str = operation["responses"]["200"]["content"]["application/json"]["schema"]["$ref"]
    return ref.rsplit("/", 1)[-1]


def typescript_client(contract: dict[str, Any]) -> str:
    out = [HEADER, f"import {{ call }} from './{RUNTIME.removesuffix('.ts')}'", f"export {{ ApiError }} from "
           f"'./{RUNTIME.removesuffix('.ts')}'\n"]  # fmt: skip
    for name, schema in contract["components"]["schemas"].items():
        if name != "BusinessError":
            out.append(_interface(name, schema) + "\n")
    methods, bodies = [], []
    for path, operations in contract["paths"].items():
        for method, operation in operations.items():
            name = operation["operationId"]
            response = _response_of(operation)
            request = response.removesuffix("Response") + "Request"
            rules = ", ".join(operation.get("x-rules", []))
            methods.append(f"  /** {operation.get('summary', name)} (rules {rules}) */")
            methods.append(f"  {name}(request: {request}): Promise<{response}>")
            body = "true" if "requestBody" in operation else "false"
            bodies.append(f"    {name}: (request) => call<{response}>(fetchImpl, baseUrl, '{method.upper()}', "
                          f"'{path}', request, {body}),")  # fmt: skip
    out.append("export interface Api {\n" + "\n".join(methods) + "\n}\n")
    out.append("/** The client over fetch; `baseUrl` is where the backend runs (same origin by default). */\n"
               "export function createApi(baseUrl = '', fetchImpl: typeof fetch = (input, init) => fetch(input, init))"
               ": Api {\n  return {\n" + "\n".join(bodies) + "\n  }\n}\n")  # fmt: skip
    return "\n".join(out)
